"""Summarize the actual fresh Studio research; excludes CLI overhead in prompt counts."""
import collections,json,pathlib,re,subprocess
import tiktoken
from ilustre_rerun import RUN,PREVIOUS,ROOT,read,write,digest
subprocess.run(['node','--import',str(ROOT/'src-ui/test/register-raw-loader.mjs'),str(ROOT/'scripts/glossary-research-lab/ilustre_rerun_summary.mjs'),str(RUN)],check=True)
s=read(RUN/'study.json');summary=read(RUN/'entry-summary.json');entry=summary['draft'];old=read(PREVIOUS/'input.json');e=tiktoken.get_encoding('o200k_base');count=lambda x:len(e.encode(x,disallowed_special=()))
records=[json.loads(l)for l in (RUN/'requests.jsonl').read_text().splitlines()];records=[r for r in records if r['status']=='ok']
ops={p.parent.name:read(p)for p in (RUN/'operations').glob('*/native-input.json')}
def operation(r):return next(v for k,v in ops.items()if '/operations/'+k+'/'in r['dir'])
phase=collections.defaultdict(lambda:{'calls':0,'requestSeconds':0,'promptTokens':0,'codexInputTokens':0,'outputTokens':0,'cachedInputTokens':0})
for r in records:
 op=operation(r);t=phase[r['stage']];t['calls']+=1;t['requestSeconds']+=r['seconds'];t['promptTokens']+=count(op['prompt']);t['codexInputTokens']+=r['usage']['input_tokens'];t['outputTokens']+=r['usage']['output_tokens'];t['cachedInputTokens']+=r['usage'].get('cached_input_tokens',0)
actual_trans=[r for r in records if r['stage']=='9'and operation(r)['kind']=='translate']
assert len(actual_trans)==4 and summary['entryTrialsCurrent']
# Matched production/editor prompt formatting, exactly the same denominator as the prior measurement.
pattern=re.compile(r'(<glossary_info format="json">\n)(.*?)(\n</glossary_info>)',re.S);matched=[]
for bi in range(4):
 baseline=(PREVIOUS/f'prompt-only/batch-{bi+1}-long.txt').read_text();before=json.loads(pattern.search(baseline)[2]);forms=[x['sourceTerm']for x in before if 'sourceTerm'in x]
 new=[{'sourceTerm':f,'targetVariants':[{'text':v,**({'note':entry['targetVariantNotes'][i]}if entry['targetVariantNotes'][i]else{})}for i,v in enumerate(entry['targetTerms'])]}for f in forms]
 if entry['notesToTranslators']:new.append({'sourceTerms':forms,'globalNotes':[entry['notesToTranslators']]})
 if entry.get('footnote'):
  for x in new:
   if 'sourceTerm'in x:x['footnotes']=[entry['footnote']]
 block=json.dumps(new,ensure_ascii=False,separators=(',',':'),sort_keys=True);after=pattern.sub(lambda m:m[1]+block+m[3],baseline)
 assert pattern.sub(lambda m:m[1]+m[3],baseline)==pattern.sub(lambda m:m[1]+m[3],after)
 (RUN/f'production-prompt-{bi+1}.txt').write_text(after);matched.append({'batch':bi+1,'paragraphs':len(old['batches'][bi]),'before':count(baseline),'after':count(after),'saved':count(baseline)-count(after),'glossaryTokens':count(block)})
before=sum(x['before']for x in matched);after=sum(x['after']for x in matched)
# The Studio test path retains capitalized surface-form hints separately; count that path symmetrically too.
studio=[]
for r in actual_trans:
 op=operation(r);p=op['prompt'];hints=json.loads(pattern.search(p)[2]);shared=[h for h in hints if 'sourceTerms'in h];assert not shared
 current_forms=[h['sourceTerm']for h in hints if 'sourceTerm'in h]
 long=[{'sourceTerm':f,'targetVariants':[{'text':v,'note':old['term']['target_variant_notes'][i]}for i,v in enumerate(old['term']['target_terms'])]}for f in current_forms]
 long.append({'sourceTerms':current_forms,'globalNotes':[old['term']['notes_to_translators']]});long_block=json.dumps(long,ensure_ascii=False,separators=(',',':'),sort_keys=True)
 baseline=pattern.sub(lambda m:m[1]+long_block+m[3],p);studio.append({'forms':current_forms,'before':count(baseline),'after':count(p),'requestSeconds':r['seconds'],'inputTokens':r['usage']['input_tokens'],'outputTokens':r['usage']['output_tokens'],'cachedInputTokens':r['usage'].get('cached_input_tokens',0)})
baseline_native=read('/tmp/gnosis-studio-native-export.json');baseline_cost={'calls':0,'promptBodyTokens':0,'outputTokens':0,'nativeInputTokens':0}
for c in baseline_native['cache'].values():
 q=c.get('request',{});v=c.get('value',{});u=c.get('metrics',{}).get('usage')or{};kind=q.get('kind')
 if kind not in ['ai','translate']or not u.get('input_tokens'):continue
 prompt=q['payload'].get('prompt')if kind=='ai'else v.get('promptText')
 baseline_cost['calls']+=1;baseline_cost['promptBodyTokens']+=count(prompt);baseline_cost['outputTokens']+=u['output_tokens'];baseline_cost['nativeInputTokens']+=u['input_tokens']
baseline_cost['automatedStageSeconds']=sum(r.get('elapsedMs',0)for t in baseline_native['timing']['steps'].values()for r in t['runs'])/1000
write(RUN/'previous-native-cost.json',baseline_cost)
prior_metrics=read(PREVIOUS/'comparison.json')['translation'];translations_seconds=sum(x['requestSeconds']for x in studio)
quality={};reviews=[];comp=RUN/'comparison'
if (comp/'blind/mapping.json').exists():
 mapping={m['id']:m for m in read(comp/'blind/mapping.json')};q=collections.Counter()
 for path in (comp/'judging').glob('primary-*/grades.json'):
  for g in read(path):
   side=mapping[g['id']]['shortSide'];other='B'if side=='A'else'A';q['fresh:'+g['accuracy'+side]]+=1;q['old:'+g['accuracy'+other]]+=1;q['freshStyle:'+g['naturalness'+side]]+=1;q['oldStyle:'+g['naturalness'+other]]+=1
   reviews.append({'id':g['id'],'freshSide':side,**g})
 quality=dict(q)
confirmation=[{'stage':p.parent.name,'grades':read(p)}for p in (comp/'judging').glob('confirmation-*/grades.json')]
judge_records=[json.loads(l)for l in (comp/'requests.jsonl').read_text().splitlines()if l.strip()]if (comp/'requests.jsonl').exists()else[]
judge_records=[r for r in judge_records if r['status']=='ok']
review_cost={'calls':len(judge_records),'seconds':sum(r['seconds']for r in judge_records),'codexInputTokensIncludingOverhead':sum(r['usage']['input_tokens']for r in judge_records),'outputTokens':sum(r['usage']['output_tokens']for r in judge_records)}
final_words=sum(len(n.split())for n in entry['targetVariantNotes'])+len(entry['notesToTranslators'].split());total_prompt=sum(t['promptTokens']for t in phase.values());total_output=sum(t['outputTokens']for t in phase.values())
result={'previousNativeResearch':baseline_cost,'generatedNotes':entry,'finalUniqueNoteWords':final_words,'initialProposedNoteWords':{c['text']:len(c.get('note','').split())for c in s['steps']['6']['value']['candidates']},'researchPhases':dict(phase),'modelCalls':len(records),'totalPromptBodyTokens':total_prompt,'totalOutputTokens':total_output,
 'summedRequestSeconds':sum(r['seconds']for r in records),'summedAutomatedStageSeconds':sum(x['elapsedMs']/1000 for t in s['timing']['steps'].values()for x in t['runs']),
 'matchedProductionPrompt':{'batches':matched,'before':before,'after':after,'saved':before-after,'savedPercent':100*(before-after)/before},'studioPrompt':{'batches':studio,'before':sum(x['before']for x in studio),'after':sum(x['after']for x in studio)},
 'translationTimePer57':{'previousLongMean':prior_metrics['long']['seconds']/2,'previousHandCompactMean':prior_metrics['short']['seconds']/2,'fresh':translations_seconds,'freshCalls':4,'note':'Fresh production Studio pass vs earlier Codex harness; service/cache/alias formatting differ. Observed times, not a causal speedup.'},'quality':quality,
 'liveFilesUnchanged':{p:digest(p)==h for p,h in read(RUN/'input.json')['liveFiles'].items()},'readingAidCalls':0,'candidateProposalOldOutputTokens':804,'candidateProposalNewOutputTokens':phase['6']['outputTokens'],'confirmation':confirmation,'separateAccuracyReviewCost':review_cost}
write(RUN/'metrics.json',result);write(RUN/'blind-review.json',reviews)
write(RUN/'research-report.json',{'term':'ilustre','sourceLanguage':'es','targetLanguage':'en','entry':entry,'meanings':s['meanings'],'assignmentCounts':summary['assignmentCounts'],'candidateResearch':summary['noteResearch'],'repairResearch':summary['noteRepairReports'],'translationTrials':{k:v for k,v in s['tests'].items()if k.startswith('9:')},'metrics':result})
lines=['# Fresh ilustre research with concise usage notes','','A new isolated study used the updated production Studio stage, tool, sampling and testing modules. Inference used the existing subscription-only Codex lab transport. Frozen corpus/DLE retrievals were reused, but no old AI meanings, candidate list or notes were passed into fresh research. Existing app studies and glossary files are unchanged.','','## Generated output','','The generator proposed five candidates with notes of 16–19 words. Focused testing confirmed distinguished and enlighten; the remaining alternatives were not required. Shared translator note and reader footnote were empty. No usage note was hand-edited. Detailed explanations and provenance are preserved under candidateResearch in research-report.json.','']
for v,n in zip(entry['targetTerms'],entry['targetVariantNotes']):lines+=['**'+v+'** ('+str(len(n.split()))+' words): '+n,'']
lines+=['## Matched production translation prompt tokens','','Same four saved 15/15/15/12 paragraph batches, same source context and instructions, same normal Gnosis editor formatter as the prior prompt-only measurement. Only glossary note content changes. o200k_base is empirically checked against saved native usage; no Codex fixed instructions, output schema or provider framing are counted.','','| Condition | Unique note words | Prompt tokens / 57 paragraphs | Reduction from old |','|---|---:|---:|---:|',f'| Old saved notes | 229 | {before:,} | — |','| Earlier manually compacted notes | 32 | 20,515 | 7.47% |',f'| Freshly generated notes | {final_words} | {after:,} | {100*(before-after)/before:.2f}% |','','The actual Studio testing path also retains differently capitalized matching surfaces as separate hint records, unlike the normal editor batch formatter. Its token comparison is therefore reported separately in metrics.json, using the same aliases in both conditions. The older controlled translation harness used the normal editor formatter; raw request totals must not be mixed between these paths.','','## Automated work and timings','','| Stage | Model calls | Production prompt tokens | Output tokens (Codex receipt) | Summed request seconds |','|---|---:|---:|---:|---:|']
for k,t in phase.items():lines.append(f"| {k} | {t['calls']} | {t['promptTokens']:,} | {t['outputTokens']:,} | {t['requestSeconds']:.3f} |")
lines+=['',f'Fresh automated-stage time: {result["summedAutomatedStageSeconds"]:.3f} seconds, excluding researcher review and test-adapter setup. Summed actual model request time: {result["summedRequestSeconds"]:.3f} seconds; {len(records)} calls. Production prompt text input: {total_prompt:,} tokens. Output: {total_output:,} tokens including reasoning where reported. Codex session input totals, cached input and request details remain in metrics.json; they are not the production-prompt denominator.','',f'Observed translation-only request time for one 57-paragraph pass: earlier long-note average {prior_metrics["long"]["seconds"]/2:.3f} s; earlier manually compacted average {prior_metrics["short"]["seconds"]/2:.3f} s; fresh generated entry {translations_seconds:.3f} s. This compares the fresh Studio pass with earlier Codex harness requests; aliases, cache state, service load and sample count differ. It does not establish a reliable causal speedup or native API latency.','',f'Candidate generation produced {phase["6"]["outputTokens"]:,} output tokens versus 804 in the original native run, because the new response separately explains proposals. Research output is not uniformly smaller; the predictable gain is the repeated translation prompt. Generation timing also differs in transport (native API vs Codex), so do not attribute its latency difference to notes alone.','','## Whole-research comparison (different transport and work)' , '', f'The original native study made {baseline_cost["calls"]} completed recorded model calls, with {baseline_cost["promptBodyTokens"]:,} locally counted production-prompt tokens and {baseline_cost["outputTokens"]:,} provider output tokens. The fresh study made {len(records)} calls, with {total_prompt:,} production-prompt tokens and {total_output:,} output tokens. Automated stage time was {baseline_cost["automatedStageSeconds"]:.3f} vs {result["summedAutomatedStageSeconds"]:.3f} seconds. These figures describe completed workflows, not an isolated note-policy effect. The fresh study needed fewer validation attempts, applied source corrections before testing and did not request reading aids. Codex and native API have different overhead and reasoning settings. No dollar savings are inferred.', '', '## Source review and workflow differences','','The small discovery sample again missed the two verb uses. Complete assignment flagged them unmatched. Source review verified ilustrar in [DLE](https://dle.rae.es/ilustrar), added the understanding/illumination verb sense, and assigned both occurrences. The descendant paragraph was again initially classified as inherited distinction; review of its source neighbors corrected it to personal distinction before generating candidates. Final counts are 2 lineage, 46 personal distinction, 7 honorific, 2 verb. These corrections are recorded under review-decisions; they are not evidence that brevity solved meaning classification.','','Optional author/internet-source checks and their consolidation were skipped for ordinary inherited vocabulary, as before. No fixed expression requiring a split was proposed; optional compound research was skipped. All 57 source paragraphs remained in the final test. Current reading aids are on demand, so no preliminary bilingual translations were requested; the old run included them.','','## Accuracy review','','Raw blinded source-based review results (fresh vs earlier long-note translations):','','```json',json.dumps(quality,indent=2),'```','','No meaningful accuracy loss was found in the 57 fresh translations. The primary reviewer marked 10 fresh paragraphs and 4 old paragraphs with minor style issues; neither had a clear fluency problem. The old bones recast was flagged in both blinded orders, but its severity is disputed because metonymic explicitation is plausible; it is not counted as a proven accuracy gain. See [FINAL-REVIEW.md](FINAL-REVIEW.md) for source-based adjudication. Quality review uses source and neighboring paragraphs, with identities hidden; not compliance with the old long notes. One fresh full pass is compared against the earlier first-pass 57-paragraph generation; repeat generations were not requested just to increase sample counts. This is one word and a finite corpus, not a universal guarantee.','', f'The separate calibration, blind review and confirmation used {review_cost["calls"]} calls and {review_cost["seconds"]:.3f} summed request seconds. This experimental review cost is excluded from research and translation timings. Its complete input count includes Codex overhead and is not used for production token-savings claims.', '', 'The production meaning tests and final 57-paragraph test passed without repairs. The note text did not grow during validation. The adjective and verb target forms match the earlier final entry. Research reports are outside the translator prompt.','', '## Preservation and reproducibility','','The earlier app study and saved glossary hashes still match: '+str(all(result['liveFilesUnchanged'].values()))+'. New files live only in this lab run. Frozen code hashes, source receipts, model requests, prompts and responses are retained. Test-adapter argument/return-value repairs are recorded in freeze.json; saved model responses were reused and production prompts were unchanged. The separate blinded review has its own request ledger.']
(RUN/'REPORT.md').write_text('\n'.join(lines)+'\n');print(json.dumps({k:result[k]for k in ['modelCalls','finalUniqueNoteWords','totalPromptBodyTokens','totalOutputTokens','summedRequestSeconds','summedAutomatedStageSeconds','matchedProductionPrompt','translationTimePer57','quality']},indent=2))
